#!/usr/bin/env node
// Structural evals for skills generated by vajra.
//
// Usage:
//   node evals/eval.mjs prompt <case.json> <out-dir>   print the generation prompt for an agent
//   node evals/eval.mjs check  <case.json> <skill-dir> [--json]   validate and assert expectations
//
// A case describes a declaration and what any good generated skill must satisfy. Assertions are
// structural (profile values, promotion gates, lifecycles, rails, domain fit), never exact
// playbook names, so they hold across model versions and wording.

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { validateSkill } from "../skills/vajra/scripts/validate.mjs";

export function loadCase(file) {
  return JSON.parse(fs.readFileSync(file, "utf8"));
}

export function prompt(c, outDir) {
  const name = path.basename(path.resolve(outDir));
  return [
    "/vajra",
    "",
    "Generate mode. This is a non-interactive evaluation run.",
    "",
    `Declaration: ${c.declaration}`,
    "",
    `Answers to questions you would ask: ${c.answers || "none"}`,
    "",
    "Do not ask questions. For every open question take your recommendation and record it as \"assumed\" in the consult log.",
    `Name the skill \`${name}\`, write it to \`${path.resolve(outDir)}\`, and validate it until it passes.`,
    "",
  ].join("\n");
}

function matches(actual, want) {
  if (want && typeof want === "object" && !Array.isArray(want)) {
    if (want.oneOf) return want.oneOf.includes(actual);
    const arr = Array.isArray(actual) ? actual : [];
    return (want.includes || []).every((x) => arr.includes(x)) && (want.excludes || []).every((x) => !arr.includes(x));
  }
  if (Array.isArray(want)) return Array.isArray(actual) && actual.length === want.length && want.every((x) => actual.includes(x));
  return actual === want;
}

export function check(c, dir) {
  const r = validateSkill(dir);
  const results = [];
  const add = (name, pass, detail) => results.push({ name, pass, detail });
  const e = c.expect || {};

  add("validator passes", r.ok, r.errors.join("; "));
  if (e.profile) {
    for (const [axis, want] of Object.entries(e.profile)) {
      const got = r.profile ? r.profile[axis] : undefined;
      add(`profile ${axis}`, matches(got, want), `got ${JSON.stringify(got)}, want ${JSON.stringify(want)}`);
    }
  }
  if (e.playbooks) {
    const n = r.nodes.length;
    add("playbook count", n >= (e.playbooks.min ?? 0) && n <= (e.playbooks.max ?? Infinity), `got ${n}, want ${e.playbooks.min}-${e.playbooks.max}`);
  }
  const promos = r.nodes.filter((n) => n.promotes).map((n) => n.promotes);
  for (const p of e.promotes || []) {
    const [from, to] = p.split("->");
    const ok = promos.some((q) => { const [f, t] = q.split("->"); return (from === "*" || f === from) && (to === "*" || t === to); });
    add(`gate promotes ${p}`, ok, `gates promote: ${promos.join(", ") || "nothing"}`);
  }
  for (const l of e.lifecycles_absent || []) {
    const hit = r.nodes.filter((n) => n.lifecycle === l).map((n) => n.id);
    add(`no ${l} playbooks`, hit.length === 0, hit.join(", "));
  }
  if (e.human_gate_on_promotion) {
    const bad = r.nodes.filter((n) => n.promotes && n.humanGates === 0).map((n) => n.id);
    add("every promotion gate stops at a human gate", bad.length === 0, bad.join(", "));
  }
  if (e.irreversible !== undefined) {
    const any = r.nodes.some((n) => n.irreversibleSteps > 0);
    add(e.irreversible ? "has [irreversible] steps" : "has no [irreversible] steps", any === e.irreversible, "");
  }
  if (e.guarded_irreversible) {
    const bad = r.nodes.filter((n) => n.irreversibleSteps > 0 && n.guards.length === 0).map((n) => n.id);
    add("every [irreversible] step has a guarded command", bad.length === 0, bad.join(", "));
  }
  if (e.checks_on_kept) {
    const bad = r.nodes.filter((n) => n.kind === "work" && ["tracer", "hardened"].includes(n.lifecycle) && n.checks.length === 0).map((n) => n.id);
    add("kept-code playbooks have checks", bad.length === 0, bad.join(", "));
  }
  if (e.domain_fit) {
    const generic = r.warnings.filter((w) => /names no concrete|in this domain's terms|Domain model/.test(w));
    add("speaks the domain's language (no domain-fit warnings)", generic.length === 0, generic.join("; "));
  }
  if (e.runtime) {
    const missing = r.warnings.filter((w) => /runtime|scripts\/flow\.mjs/.test(w));
    add("carries the runtime and drives runs through it", missing.length === 0, missing.join("; "));
  }
  return { id: c.id, pass: results.every((x) => x.pass), results, warnings: r.warnings };
}

const isMain = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain) {
  const [cmd, caseFile, dir] = process.argv.slice(2);
  if (!["prompt", "check"].includes(cmd) || !caseFile || !dir) {
    console.error("usage: node evals/eval.mjs prompt|check <case.json> <dir> [--json]");
    process.exit(2);
  }
  const c = loadCase(caseFile);
  if (cmd === "prompt") {
    process.stdout.write(prompt(c, dir));
    process.exit(0);
  }
  const res = check(c, dir);
  if (process.argv.includes("--json")) console.log(JSON.stringify(res, null, 2));
  else {
    for (const x of res.results) console.log(`${x.pass ? "PASS" : "FAIL"}  ${x.name}${!x.pass && x.detail ? `  (${x.detail})` : ""}`);
    for (const w of res.warnings) console.log(`WARN  ${w}`);
    console.log(`${res.pass ? "PASSED" : "FAILED"}: ${res.id}`);
  }
  process.exit(res.pass ? 0 : 1);
}
